content='''def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for row in grid for v in row)
    marker=min((v for v in cnt if v!=0), key=lambda v:cnt[v])
    pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker}
    # choose the largest orthogonally connected marker component as the stamp
    unseen=set(pts); comps=[]
    while unseen:
        todo=[unseen.pop()]; comp=set(todo)
        while todo:
            r,c=todo.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen: unseen.remove(p); comp.add(p); todo.append(p)
        comps.append(comp)
    comp=max(comps,key=len)
    r0=min(r for r,c in comp); c0=min(c for r,c in comp)
    shape={(r-r0,c-c0) for r,c in comp}
    variants=set()
    s=shape
    for _ in range(4):
        variants.add(s)
        variants.add({(r,-c) for r,c in s})
        # rotate clockwise within normalized coordinate space
        t={(c,-r) for r,c in s}; ar=min(r for r,c in t); ac=min(c for r,c in t)
        s={(r-ar,c-ac) for r,c in t}
    out=[row[:] for row in grid]
    for sh in variants:
        mh=max(r for r,c in sh)+1; mw=max(c for r,c in sh)+1
        for r in range(h-mh+1):
            for c in range(w-mw+1):
                cells=[(r+dy,c+dx) for dy,dx in sh]
                if all(grid[y][x]==0 for y,x in cells):
                    for y,x in cells: out[y][x]=marker
    return out
'''
